+function getEnvConfig(key: string, defaultValue?: string): string | undefined {
+  return process.env[key] || defaultValue
+}
+
+function getEnvNumber(key: string, defaultValue: number): number {
+  const val = process.env[key]
+  return val ? parseInt(val, 10) : defaultValue
+}
+
+export function detectBreach(vector: any): BreachDetectionResult {
+  try {
+    const breachThreshold = getEnvNumber('ORCH_BREACH_THRESHOLD', 100)
+
+    if (vector.riskLevel >= breachThreshold) {
+      return {
+        isBreach: true,
+        breachType: 'RISK_THRESHOLD',
+        severity: vector.riskLevel,
+        detectionTs: Date.now()
+      }
+    }
+
+    if (vector.triggerProofValid === false) {
+      return {
+        isBreach: true,
+        breachType: 'PROOF_VALIDATION',
+        detectionTs: Date.now()
+      }
+    }
+
+    return { isBreach: false }
+  } catch (err) {
+    console.error('[detectBreach] validation error:', err)
+    return { isBreach: false }
+  }
+}
