+export function fireOnBreach(
+  contractId: string,
+  breachType: string,
+  eventEmitter?: EventEmitter
+): void {
+  try {
+    const selfHealingRing = getSelfHealingRing()
+    if (!selfHealingRing) {
+      console.warn('[fireOnBreach] selfHealingRing not available')
+      eventEmitter?.emit('breachDetectionFailed', {
+        contractId,
+        breachType,
+        reason: 'selfHealingRing unavailable'
+      })
+      return
+    }
+
+    selfHealingRing.fire({
+      contractId,
+      breachType,
+      detectionTs: Date.now()
+    }).catch((err: Error) => {
+      console.error('[fireOnBreach] error firing ring:', err)
+      eventEmitter?.emit('breachDetectionFailed', {
+        contractId,
+        breachType,
+        reason: err.message
+      })
+    })
+  } catch (err) {
+    console.error('[fireOnBreach] unexpected error:', err)
+    eventEmitter?.emit('breachDetectionFailed', {
+      contractId,
+      breachType,
+      reason: err instanceof Error ? err.message : 'unknown error'
+    })
+  }
+}
