+export async function discoverPairings(
+  context: BreachContext
+): Promise<{ newPartyId: string; newParcels: string[] } | null> {
+  try {
+    const poolKey = `ORCH_REPLACEMENT_POOL_${context.contractId}`
+    const poolJson = getEnvConfig(poolKey)
+
+    if (!poolJson) {
+      console.warn(`[discoverPairings] no replacement pool for ${context.contractId}`)
+      return null
+    }
+
+    const candidates: ReplacementCandidate[] = JSON.parse(poolJson)
+
+    for (const candidate of candidates) {
+      if (!candidate.availableParcels) continue
+
+      const covers = context.parcelsAffected.every(parcel =>
+        candidate.availableParcels.includes(parcel)
+      )
+
+      if (covers) {
+        return {
+          newPartyId: candidate.partyId,
+          newParcels: context.parcelsAffected
+        }
+      }
+    }
+
+    return null
+  } catch (err) {
+    console.error('[discoverPairings] error:', err)
+    return null
+  }
+}
