+export async function openRemediationMatter(
+  contractId: string,
+  context: any
+): Promise<{ warRoomTaskId?: string; error?: string }> {
+  try {
+    const agreement = await fetchRemediationAgreement(contractId)
+    if (!agreement) {
+      console.warn(`[openRemediationMatter] no agreement for ${contractId}`)
+      return { error: 'no_remediation_agreement' }
+    }
+
+    const payload: RemediationMatter = {
+      contractId,
+      breachType: context.breachType || 'UNKNOWN',
+      affectedParcels: context.parcelsAffected || [],
+      replacementParty: context.newPartyId || '',
+      costShareModel: agreement.costShareModel,
+      initiatorId: 'system',
+      timestamp: Date.now()
+    }
+
+    if (!agreement.warRoomEndpoint) {
+      console.warn('[openRemediationMatter] no warRoom endpoint')
+      return { error: 'no_endpoint' }
+    }
+
+    const response = await fetch(agreement.warRoomEndpoint, {
+      method: 'POST',
+      headers: { 'Content-Type': 'application/json' },
+      body: JSON.stringify(payload)
+    }).catch((err: Error) => {
+      console.error('[openRemediationMatter] fetch error:', err)
+      return null
+    })
+
+    if (!response || !response.ok) {
+      console.error('[openRemediationMatter] failed to open matter')
+      return { error: 'endpoint_unreachable' }
+    }
+
+    const result = await response.json()
+    return { warRoomTaskId: result.taskId }
+  } catch (err) {
+    console.error('[openRemediationMatter] error:', err)
+    return { error: err instanceof Error ? err.message : 'unknown_error' }
+  }
+}
